import type { ImageMime } from "./SnapshotPhotoRules.ts";

/** Private immutable media only. Implementations must reject escapes from the configured root. */
export interface SnapshotMediaReader {
  readonly size: number;
  read(maxBytes: number): Promise<Uint8Array>;
  assertUnchanged(): Promise<void>;
  close(): void;
}
export interface SnapshotMediaExpected {
  readonly bytes: number;
  readonly sha256: string;
  readonly mime: ImageMime;
}
export interface SnapshotMediaPort {
  openSource(uri: string): Promise<SnapshotMediaReader>;
  /** New filename generated by the engine, not an imported path. Publish only after readback
   * verifies every byte; an existing target may be reused only when its bytes match exactly.
   * Failed/aborted work must never replace another file. */
  publishVerified(filename: string, expected: SnapshotMediaExpected,
    write: (append: (bytes: Uint8Array) => Promise<void>) => Promise<void>): Promise<string>;
}
export interface SnapshotMediaProgress {
  readonly phase: "EMBEDDED" | "WRITING" | "PUBLISHED";
  readonly completedBytes: number;
  readonly totalBytes: number;
}
export interface SnapshotMediaSettings {
  readonly files?: SnapshotMediaPort;
  readonly restoreId?: string;
  readonly onMediaProgress?: (progress: SnapshotMediaProgress) => void;
}
export function snapshotMediaProgress(settings: SnapshotMediaSettings, phase: SnapshotMediaProgress["phase"], completedBytes: number, totalBytes: number): void {
  try { settings.onMediaProgress?.({ phase, completedBytes, totalBytes }); }
  catch { /* Observers do not change persistence outcomes. */ }
}
